const job=(kind,f,extra={})=>({operationId:randomUUID(),kind,...(f?.bridgeId?{bridgeId:f.bridgeId}:{}),...extra});
async function prepare(f,adapter=migration()){const j=job('prepare',f,{expectedAccountGeneration:(await state(f.a)).generation});const result=await adapter.run(req(f,j),j);assert.equal(result.status,'prepared');return{j,result};}
async function dual(f){const j=job('dual',f,{expectedBridgeGeneration:1,accountRecoveryVersion:1,recoverySaved:true}),result=await migration().run(req(f,j),j);assert.equal(result.status,'dual');return{j,result};}
async function finalize(f,adapter=migration()){const j=job('finalize',f,{expectedBridgeGeneration:2}),result=await adapter.run(req(f,j),j);assert.equal(result.status,'finalized');return{j,result};}
