 const tables=(await db.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' AND name NOT GLOB '_cf_*' ORDER BY name").all()).results.map(x=>x.name),rows={};for(const t of tables)rows[t]=(await db.prepare('SELECT * FROM '+t).all()).results;
 const key=await crypto.subtle.generateKey({name:'AES-GCM',length:256},false,['encrypt','decrypt']),iv=crypto.getRandomValues(new Uint8Array(12));const cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,new TextEncoder().encode(JSON.stringify(rows)));const file=path.join(OUT,'encrypted-synthetic-'+randomUUID()+'.bin');fs.writeFileSync(file,new Uint8Array([...iv,...new Uint8Array(cipher)]));const bytes=fs.readFileSync(file),decoded=JSON.parse(new TextDecoder().decode(await crypto.subtle.decrypt({name:'AES-GCM',iv:bytes.subarray(0,12)},key,bytes.subarray(12))));
