 let remaining=Object.keys(decoded).filter(t=>decoded[t].length&&!t.startsWith('sync_maintenance_v2_'));while(remaining.length){let progress=false;for(const t of [...remaining]){try{await restored.batch(decoded[t].map(row=>{const keys=Object.keys(row);return restored.prepare('INSERT INTO '+t+'('+keys.join(',')+')VALUES('+keys.map(()=>'?').join(',')+')').bind(...keys.map(k=>row[k]));}));remaining=remaining.filter(x=>x!==t);progress=true;}catch{}}if(!progress)throw Error('isolated_restore_failed');}
 for(const c of decoded.sync_maintenance_v2_control||[])await restored.prepare("INSERT INTO sync_maintenance_v2_control(scope,contract_version,epoch,phase,updated_at)VALUES(?,2,1,'closed',?)").bind(c.scope,c.updated_at).run();
