 for(const c of decoded.sync_maintenance_v2_control||[]){let state={phase:'closed',stop_id:null,handover_id:null};const operations=(decoded.sync_maintenance_v2_operations||[]).filter(o=>o.scope===c.scope&&['stop','handover','open'].includes(o.kind)).sort((a,b)=>a.epoch-b.epoch);for(const op of operations){const receipt=JSON.parse(op.receipt_json);assert.equal(await maintenanceDigest(receipt),op.receipt_digest);if(op.kind==='stop')state={phase:'closed',stop_id:op.operation_id,handover_id:null};else if(op.kind==='handover')state.handover_id=op.operation_id;else state.phase='open';await restored.prepare('UPDATE sync_maintenance_v2_control SET epoch=?,phase=?,stop_id=?,handover_id=?,transition_id=?,updated_at=? WHERE scope=? AND epoch=?').bind(op.epoch+1,state.phase,state.stop_id,state.handover_id,op.operation_id,op.epoch+1===c.epoch?c.updated_at:op.updated_at,c.scope,op.epoch).run();}}
